// Nomad Outdoors event board: Cloudflare Worker + D1.
// Bindings needed: D1 database bound as DB, secret ORGANISER_CODE.
// The page, manifest and icons are embedded below (generated by build.py).

const HTML = "<!doctype html>\n<html lang=\"en-GB\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1,viewport-fit=cover\">\n<title>Event board \u00b7 Nomad Outdoors</title>\n<meta name=\"description\" content=\"Upcoming drives, wadi trips and camps. Tap an event to see the details and sign up.\">\n<meta property=\"og:title\" content=\"Nomad Outdoors\">\n<meta property=\"og:description\" content=\"Upcoming drives, wadi trips and camps. Tap an event to see the details and sign up.\">\n<meta property=\"og:type\" content=\"website\">\n<meta property=\"og:url\" content=\"__ORIGIN__/board\">\n<meta name=\"robots\" content=\"noindex\">\n<meta property=\"og:site_name\" content=\"Nomad Outdoors\">\n<meta property=\"og:image\" content=\"__ORIGIN__/og-image.png\">\n<meta property=\"og:image:width\" content=\"1200\">\n<meta property=\"og:image:height\" content=\"630\">\n<meta property=\"og:image:alt\" content=\"Nomad Outdoors: drives, wadis, camps and campfires\">\n<meta name=\"twitter:card\" content=\"summary_large_image\">\n<meta name=\"theme-color\" content=\"#17201E\">\n<link rel=\"manifest\" href=\"/manifest.webmanifest\">\n<link rel=\"apple-touch-icon\" href=\"/apple-touch-icon.png\">\n<meta name=\"apple-mobile-web-app-capable\" content=\"yes\">\n<meta name=\"apple-mobile-web-app-title\" content=\"Nomad\">\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n<link rel=\"stylesheet\" href=\"https://fonts.googleapis.com/css2?family=Big+Shoulders+Display:wght@600;800&family=Public+Sans:wght@400;500;600;700&family=IBM+Plex+Mono:wght@500&display=swap\">\n<style>\nhtml{-webkit-text-size-adjust:100%}\nbody{margin:0;padding-top:env(safe-area-inset-top,0px)}\n[hidden]{display:none!important}\n:root{\n  --bg:#EDF0EC;--surface:#FFFFFF;--surface-2:#E3E8E3;--ink:#17201E;--muted:#586562;--line:#D0D8D3;\n  --accent:#0E6B62;--accent-ink:#FFFFFF;--amber:#A86F00;--amber-soft:#FBEFCB;--danger:#B3261E;\n  --t-desert:#B86E00;--t-wadi:#17758A;--t-camping:#4A7628;--t-overland:#8A4A28;--t-social:#7A3E78;\n  --display:\"Big Shoulders Display\",\"Arial Narrow\",Impact,sans-serif;\n  --body:\"Public Sans\",system-ui,-apple-system,\"Segoe UI\",sans-serif;\n  --mono:\"IBM Plex Mono\",ui-monospace,Menlo,Consolas,monospace;\n}\n@media (prefers-color-scheme: dark){\n  :root{\n    color-scheme:dark;\n    --bg:#101615;--surface:#18201F;--surface-2:#212B29;--ink:#E5ECE9;--muted:#9AA9A5;--line:#2D3936;\n    --accent:#4DB6A9;--accent-ink:#0A1211;--amber:#F0B93A;--amber-soft:#382C0F;--danger:#F2877F;\n    --t-desert:#EBA43A;--t-wadi:#5CC0D4;--t-camping:#93C466;--t-overland:#D98E66;--t-social:#D08ACD;\n  }\n}\n*{box-sizing:border-box}\nbody{background:var(--bg);color:var(--ink);font-family:var(--body);font-size:15px;line-height:1.5;padding-inline:16px;padding-block:0 48px}\n.wrap{max-width:720px;margin:0 auto}\nbutton,input,select,textarea{font:inherit;color:inherit}\na{color:var(--accent)}\n:focus-visible{outline:2px solid var(--accent);outline-offset:2px}\n\n.top{display:flex;align-items:flex-end;justify-content:space-between;gap:16px;flex-wrap:wrap;padding-block:28px 20px;border-bottom:2px solid var(--ink);margin-bottom:24px}\n.brand h1{font-family:var(--display);font-weight:800;font-size:44px;line-height:.9;letter-spacing:.01em;text-transform:uppercase;margin:0}\n.brand p{margin:6px 0 0;color:var(--muted);font-size:13px;letter-spacing:.06em;text-transform:uppercase}\n\n.btn{display:inline-flex;align-items:center;justify-content:center;gap:8px;border:1.5px solid var(--ink);background:transparent;padding:9px 16px;border-radius:6px;font-weight:600;cursor:pointer;text-decoration:none;color:var(--ink)}\n.btn:hover{background:var(--surface-2)}\n.btn.primary{background:var(--accent);border-color:var(--accent);color:var(--accent-ink)}\n.btn.primary:hover{filter:brightness(1.08)}\n.btn.small{padding:6px 12px;font-size:13px}\n.btn.danger{border-color:var(--danger);color:var(--danger)}\n.btn.link{border:none;padding:6px 0;color:var(--muted)}\n.btn.link:hover{background:none;color:var(--ink)}\n.btn[disabled]{opacity:.5;cursor:not-allowed}\n\n.notice{background:var(--amber-soft);border-left:3px solid var(--amber);padding:10px 14px;border-radius:0 6px 6px 0;margin-bottom:20px;font-size:14px}\n.flash{background:var(--surface);border:1px solid var(--line);padding:10px 14px;border-radius:6px;margin-bottom:20px;font-size:14px}\n\n.label{font-size:11px;letter-spacing:.1em;text-transform:uppercase;color:var(--muted);font-weight:600}\nh2.section{font-family:var(--display);font-weight:600;font-size:22px;text-transform:uppercase;letter-spacing:.03em;margin:32px 0 12px}\n\n.tag{display:inline-flex;align-items:center;gap:6px;font-size:12px;font-weight:600;letter-spacing:.04em;text-transform:uppercase;color:var(--tc,var(--muted))}\n.tag::before{content:\"\";width:8px;height:8px;border-radius:2px;background:var(--tc,var(--muted))}\n.t-desert{--tc:var(--t-desert)}.t-wadi{--tc:var(--t-wadi)}.t-camping{--tc:var(--t-camping)}.t-overland{--tc:var(--t-overland)}.t-social{--tc:var(--t-social)}\n.chip{display:inline-block;font-size:11px;font-weight:700;letter-spacing:.06em;text-transform:uppercase;padding:2px 8px;border-radius:99px;background:var(--surface-2);color:var(--muted)}\n.chip.full{background:var(--amber-soft);color:var(--amber)}\n.chip.in{background:var(--accent);color:var(--accent-ink)}\n\n/* next-up ticket */\n.ticket{display:grid;grid-template-columns:120px 1fr;background:var(--surface);border:1.5px solid var(--ink);border-radius:10px;overflow:hidden;cursor:pointer;text-align:left;width:100%;padding:0}\n.ticket:hover{box-shadow:0 4px 0 var(--ink)}\n.stub{background:var(--ink);color:var(--bg);display:flex;flex-direction:column;align-items:center;justify-content:center;padding:18px 8px;gap:2px;border-right:2px dashed var(--bg)}\n.stub .dow{font-size:12px;letter-spacing:.14em;font-weight:700}\n.stub .day{font-family:var(--display);font-weight:800;font-size:56px;line-height:.9}\n.stub .mon{font-size:12px;letter-spacing:.14em;font-weight:700}\n.ticket-body{padding:18px 20px;display:flex;flex-direction:column;gap:10px;min-width:0}\n.ticket-body h3{font-family:var(--display);font-weight:800;font-size:30px;line-height:1;margin:0;text-transform:uppercase;text-wrap:balance}\n.meta{display:flex;flex-wrap:wrap;gap:6px 18px;font-size:14px;color:var(--muted)}\n.meta b{color:var(--ink);font-weight:600}\n.mono{font-family:var(--mono);font-variant-numeric:tabular-nums}\n.sponsor-line{font-size:13px;color:var(--amber);font-weight:600}\n\n/* event list */\n.list{display:flex;flex-direction:column;border-top:1px solid var(--line)}\n.row{display:grid;grid-template-columns:64px 1fr auto;gap:16px;align-items:center;padding:14px 4px;border:none;border-bottom:1px solid var(--line);background:none;text-align:left;cursor:pointer;width:100%}\n.row:hover{background:var(--surface)}\n.dblock{text-align:center;line-height:1.05}\n.dblock .d{font-family:var(--display);font-weight:800;font-size:30px}\n.dblock .m{font-size:11px;letter-spacing:.12em;font-weight:700;color:var(--muted)}\n.row h4{margin:2px 0 2px;font-size:16px;font-weight:700}\n.row .sub{font-size:13px;color:var(--muted)}\n.count{text-align:right;font-size:13px;color:var(--muted);white-space:nowrap}\n.count b{display:block;font-family:var(--mono);font-size:16px;color:var(--ink)}\n.empty{padding:28px 0;color:var(--muted)}\n\ndetails.past summary{cursor:pointer;color:var(--muted);font-weight:600;padding:8px 0}\n\n/* detail */\n.back{margin-bottom:16px}\n.detail-head{display:flex;flex-direction:column;gap:8px;margin-bottom:20px}\n.detail-head h2{font-family:var(--display);font-weight:800;font-size:40px;line-height:.95;text-transform:uppercase;margin:0;text-wrap:balance}\n.facts{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:1px;background:var(--line);border:1px solid var(--line);border-radius:8px;overflow:hidden;margin-bottom:20px}\n.fact{background:var(--surface);padding:12px 14px;display:flex;flex-direction:column;gap:2px;min-width:0}\n.fact .v{font-weight:600;overflow-wrap:anywhere}\n.prose{white-space:pre-wrap;max-width:65ch;margin:0}\n.kit{margin:0;padding-left:20px;display:grid;gap:4px}\n.sponsor{background:var(--amber-soft);border-radius:8px;padding:14px 16px;margin-top:20px;display:flex;flex-direction:column;gap:4px}\n.sponsor .label{color:var(--amber)}\n.actions{display:flex;flex-wrap:wrap;gap:10px;align-items:center;margin-block:20px}\n.people{display:flex;flex-direction:column;border-top:1px solid var(--line)}\n.person{display:grid;grid-template-columns:28px 1fr auto;gap:12px;padding:10px 0;border-bottom:1px solid var(--line);align-items:start}\n.person .n{font-family:var(--mono);color:var(--muted);font-size:13px;padding-top:2px}\n.person .who{font-weight:600}\n.person .what{font-size:13px;color:var(--muted)}\n.person .pax{font-size:13px;color:var(--muted);white-space:nowrap}\n.person.wait .who{color:var(--muted)}\n.bringing{display:flex;flex-wrap:wrap;gap:6px;margin-top:8px}\n.bringing span{background:var(--surface);border:1px solid var(--line);border-radius:99px;padding:3px 10px;font-size:13px}\n\n/* forms */\nform{display:flex;flex-direction:column;gap:16px;max-width:560px}\n.field{display:flex;flex-direction:column;gap:6px}\n.field label{font-weight:600;font-size:14px}\n.field .hint{font-size:12px;color:var(--muted)}\n.two{display:grid;grid-template-columns:1fr 1fr;gap:16px}\ninput,select,textarea{background:var(--surface);border:1.5px solid var(--line);border-radius:6px;padding:9px 11px;width:100%}\ninput:focus,select:focus,textarea:focus{border-color:var(--accent);outline:none}\ntextarea{min-height:96px;resize:vertical}\nfieldset{border:1px solid var(--line);border-radius:8px;padding:14px;display:flex;flex-direction:column;gap:14px;margin:0}\nlegend{padding:0 6px;font-weight:600;font-size:13px;color:var(--amber)}\n.err{color:var(--danger);font-size:13px}\n.confirm{display:flex;flex-wrap:wrap;gap:10px;align-items:center;font-size:14px}\n\n@media (max-width:520px){\n  .brand h1{font-size:36px}\n  .ticket{grid-template-columns:88px 1fr}\n  .stub .day{font-size:44px}\n  .ticket-body h3{font-size:24px}\n  .detail-head h2{font-size:32px}\n  .two{grid-template-columns:1fr}\n  .row{grid-template-columns:52px 1fr auto;gap:12px}\n}\n@media (prefers-reduced-motion:reduce){*{transition:none!important}}\n\n.foot{margin-top:40px;padding-top:16px;border-top:1px solid var(--line);display:flex;flex-direction:column;gap:6px;font-size:13px;color:var(--muted)}\n.foot button{background:none;border:none;padding:0;color:var(--accent);font-weight:600;cursor:pointer;text-decoration:underline;text-underline-offset:2px}\n.person .tel{font-family:var(--mono);font-size:13px}\n.orgbar{background:var(--ink);color:var(--bg);font-size:12px;letter-spacing:.08em;text-transform:uppercase;font-weight:700;padding:6px 12px;border-radius:0 0 6px 6px;display:inline-block;margin-bottom:12px}\n</style>\n</head>\n<body>\n<div class=\"wrap\">\n  <header class=\"top\">\n    <div class=\"brand\">\n      <h1><a href=\"/\" style=\"color:inherit;text-decoration:none\">Nomad Outdoors</a></h1>\n      <p>Event board</p>\n    </div>\n    <button class=\"btn primary\" id=\"newBtn\" hidden>Post an event</button>\n  </header>\n  <div id=\"notice\" class=\"notice\" hidden></div>\n  <main id=\"app\"><p class=\"empty\">Loading the board\u2026</p></main>\n  <footer class=\"foot\" id=\"foot\"></footer>\n</div>\n\n<script>\nconst TYPES = {\n  desert:   {label:\"Desert drive\", kit:\"Recovery tracks\\nShovel\\nTyre deflator and compressor\\nKinetic rope with soft shackles\\nSand flag\\nRadio or charged phone\\n3 L water per person\"},\n  wadi:     {label:\"Wadi trip\", kit:\"Water shoes or sturdy sandals\\nHat and sun cream\\n3 L water per person\\nSnacks\\nDry bag for phone and keys\\nSmall first aid kit\"},\n  camping:  {label:\"Camping\", kit:\"Tent, sleeping bag and mat\\nHead torch\\nCamp chair\\nFirewood (one bundle per car)\\nCool box with your own food and drink\\nRubbish bags (we leave nothing behind)\"},\n  overland: {label:\"Overlanding\", kit:\"Full recovery kit\\nSpare tyre and jack base plate\\nCompressor\\nFuel for the full route plus reserve\\n5 L water per person\\nOffline maps downloaded\"},\n  social:   {label:\"Social\", kit:\"Something to share, food or drink\\nGood stories\"}\n};\nconst DIFF = [\"Easy\",\"Moderate\",\"Hard\",\"Expert\"];\n\nconst $ = s => document.querySelector(s);\nconst esc = v => String(v ?? \"\").replace(/[&<>\"']/g, c => ({\"&\":\"&amp;\",\"<\":\"&lt;\",\">\":\"&gt;\",'\"':\"&quot;\",\"'\":\"&#39;\"}[c]));\nconst store = {\n  get(k){ try{ return localStorage.getItem(k) || \"\"; }catch(e){ return \"\"; } },\n  set(k,v){ try{ v ? localStorage.setItem(k,v) : localStorage.removeItem(k); }catch(e){} }\n};\nconst S = {events:[], signups:[], ready:false, error:\"\", isOrg:false, view:{name:\"list\"}, flash:\"\", confirmDel:false};\n\n/* ---------- helpers ---------- */\nfunction todayISO(){ const d=new Date(); d.setMinutes(d.getMinutes()-d.getTimezoneOffset()); return d.toISOString().slice(0,10); }\nfunction parse(iso){ const [y,m,d]=iso.split(\"-\").map(Number); return new Date(y,m-1,d); }\nfunction fmtDate(iso, opts){ return iso ? parse(iso).toLocaleDateString(\"en-GB\", opts) : \"\"; }\nfunction dateRange(e){\n  const a = fmtDate(e.date,{weekday:\"short\",day:\"numeric\",month:\"short\"});\n  if(e.endDate && e.endDate !== e.date) return a + \" to \" + fmtDate(e.endDate,{weekday:\"short\",day:\"numeric\",month:\"short\"});\n  return a;\n}\nfunction daysUntil(iso){ return Math.round((parse(iso) - parse(todayISO()))/86400000); }\nfunction whenChip(e){ const n = daysUntil(e.date); return n < 0 ? \"On now\" : n === 0 ? \"Today\" : n === 1 ? \"Tomorrow\" : \"In \" + n + \" days\"; }\nfunction isUpcoming(e){ return (e.endDate || e.date) >= todayISO(); }\nfunction typeOf(e){ return TYPES[e.type] ? e.type : \"social\"; }\nfunction fmtPhone(p){ const m = /^\\+971(\\d{2})(\\d{3})(\\d{4})$/.exec(p||\"\"); return m ? \"+971 \"+m[1]+\" \"+m[2]+\" \"+m[3] : (p||\"\"); }\nfunction signupsFor(id){ return S.signups.filter(s => s.eventId === id).sort((a,b) => (a.at||\"\").localeCompare(b.at||\"\")); }\nfunction split(e){\n  const all = signupsFor(e.id), cap = Number(e.capacity) || 0;\n  return cap ? {going:all.slice(0,cap), waiting:all.slice(cap), cap} : {going:all, waiting:[], cap:0};\n}\nfunction mine(e){ return S.signups.find(s => s.eventId === e.id && s.mine); }\nfunction inForm(){ return [\"edit\",\"join\",\"who\",\"org\"].includes(S.view.name); }\n\n/* ---------- API ---------- */\nasync function api(path, body){\n  const headers = {\"content-type\":\"application/json\"};\n  const phone = store.get(\"no_phone\"), code = store.get(\"no_org\");\n  if(phone) headers[\"x-phone\"] = phone;\n  if(code) headers[\"x-organiser-code\"] = code;\n  const res = await fetch(\"/api\" + path, {method: body ? \"POST\" : \"GET\", headers, body: body ? JSON.stringify(body) : undefined, cache:\"no-store\"});\n  let data = {}; try{ data = await res.json(); }catch(_){}\n  if(!res.ok){ const err = new Error(data.message || \"Something went wrong.\"); err.code = data.error; throw err; }\n  return data;\n}\nasync function load(){\n  try{\n    const d = await api(\"/board\");\n    S.events = d.events; S.signups = d.signups; S.isOrg = !!d.organiser;\n    if(store.get(\"no_org\") && !d.organiser) store.set(\"no_org\",\"\");\n    S.ready = true; S.error = \"\";\n  }catch(e){\n    S.error = e.code === \"no_database\" ? \"The board isn't connected to its database yet. Check the D1 binding is called DB.\" : \"Can't reach the board right now. Check your connection and pull to refresh.\";\n  }\n  if(!inForm()) render();\n}\n\n/* ---------- views ---------- */\nfunction go(view){ S.view = view; S.confirmDel = false; render(); window.scrollTo(0,0); }\n\nfunction render(){\n  $(\"#newBtn\").hidden = !(S.isOrg && S.view.name === \"list\");\n  const n = $(\"#notice\");\n  n.hidden = !S.error; n.textContent = S.error;\n  const app = $(\"#app\"), v = S.view;\n  if(!S.ready){ app.innerHTML = S.error ? \"\" : '<p class=\"empty\">Loading the board\u2026</p>'; renderFoot(); return; }\n  if(v.name === \"detail\") app.innerHTML = detailHTML(v.id);\n  else if(v.name === \"join\") app.innerHTML = joinHTML(v.id);\n  else if(v.name === \"edit\") app.innerHTML = editHTML(v.id);\n  else if(v.name === \"who\") app.innerHTML = whoHTML();\n  else if(v.name === \"org\") app.innerHTML = orgHTML();\n  else app.innerHTML = listHTML();\n  if(v.name === \"edit\") wireEdit(v.id);\n  if(v.name === \"join\") wireJoin(v.id);\n  if(v.name === \"who\") wireWho();\n  if(v.name === \"org\") wireOrg();\n  renderFoot();\n}\n\nfunction renderFoot(){\n  const name = store.get(\"no_name\"), phone = store.get(\"no_phone\");\n  let h = phone\n    ? '<span>This phone signs up as <b>'+esc(name || \"you\")+'</b> ('+esc(fmtPhone(phone))+'). <button data-go=\"who\">Change</button></span>'\n    : '<span>Signed up from another phone? <button data-go=\"who\">Enter your number</button> to see your sign-ups here.</span>';\n  h += S.isOrg ? '<span>Organiser mode is on. <button data-orgout>Switch off</button></span>' : '<span><button data-go=\"org\">Organiser login</button></span>';\n  $(\"#foot\").innerHTML = h;\n}\n\nfunction flashHTML(){ if(!S.flash) return \"\"; const f = S.flash; S.flash = \"\"; return '<div class=\"flash\" role=\"status\">'+esc(f)+'</div>'; }\n\nfunction countInfo(e){\n  const {going, cap} = split(e);\n  const pax = going.reduce((t,s) => t + (Number(s.people)||1), 0);\n  const chip = mine(e) ? '<span class=\"chip in\">You\\'re in</span>' : (cap && going.length >= cap ? '<span class=\"chip full\">Full \u00b7 waitlist</span>' : \"\");\n  return {cars:going.length, pax, cap, chip};\n}\n\nfunction listHTML(){\n  const up = S.events.filter(isUpcoming).sort((a,b) => (a.date+(a.meetTime||\"\")).localeCompare(b.date+(b.meetTime||\"\")));\n  const past = S.events.filter(e => !isUpcoming(e)).sort((a,b) => b.date.localeCompare(a.date)).slice(0,20);\n  let h = (S.isOrg ? '<span class=\"orgbar\">Organiser mode</span>' : '') + flashHTML();\n  if(!up.length){\n    h += '<p class=\"empty\">Nothing on the board yet. '+(S.isOrg ? 'Post the next drive and it will show here for everyone.' : 'Keep an eye on the WhatsApp group.')+'</p>';\n  } else {\n    const e = up[0], t = typeOf(e), c = countInfo(e), d = parse(e.date);\n    h += '<div class=\"label\" style=\"margin-bottom:8px\">Next up \u00b7 '+esc(whenChip(e))+'</div>';\n    h += '<button class=\"ticket\" data-open=\"'+esc(e.id)+'\">'\n      + '<div class=\"stub\"><span class=\"dow\">'+d.toLocaleDateString(\"en-GB\",{weekday:\"short\"}).toUpperCase()+'</span><span class=\"day\">'+d.getDate()+'</span><span class=\"mon\">'+d.toLocaleDateString(\"en-GB\",{month:\"short\"}).toUpperCase()+'</span></div>'\n      + '<div class=\"ticket-body\"><span class=\"tag t-'+t+'\">'+esc(TYPES[t].label)+'</span>'\n      + '<h3>'+esc(e.title)+'</h3>'\n      + '<div class=\"meta\">'+(e.meetTime?'<span>Meet <b class=\"mono\">'+esc(e.meetTime)+'</b></span>':'')+(e.meetPoint?'<span>'+esc(e.meetPoint)+'</span>':'')+'</div>'\n      + '<div class=\"meta\"><span><b class=\"mono\">'+c.cars+(c.cap?'/'+c.cap:'')+'</b> '+(t===\"social\"?'signed up':'vehicles')+'</span><span><b class=\"mono\">'+c.pax+'</b> people</span>'+(e.difficulty?'<span>'+esc(e.difficulty)+'</span>':'')+' '+c.chip+'</div>'\n      + (e.sponsorName ? '<div class=\"sponsor-line\">Supported by '+esc(e.sponsorName)+'</div>' : '')\n      + '</div></button>';\n    if(up.length > 1) h += '<h2 class=\"section\">Coming up</h2><div class=\"list\">' + up.slice(1).map(rowHTML).join(\"\") + '</div>';\n  }\n  if(past.length) h += '<details class=\"past\"><summary>Past events ('+past.length+')</summary><div class=\"list\">'+past.map(rowHTML).join(\"\")+'</div></details>';\n  return h;\n}\n\nfunction rowHTML(e){\n  const t = typeOf(e), c = countInfo(e), d = parse(e.date);\n  return '<button class=\"row\" data-open=\"'+esc(e.id)+'\">'\n    + '<div class=\"dblock\"><div class=\"m\">'+d.toLocaleDateString(\"en-GB\",{weekday:\"short\"}).toUpperCase()+'</div><div class=\"d\">'+d.getDate()+'</div><div class=\"m\">'+d.toLocaleDateString(\"en-GB\",{month:\"short\"}).toUpperCase()+'</div></div>'\n    + '<div><span class=\"tag t-'+t+'\">'+esc(TYPES[t].label)+'</span><h4>'+esc(e.title)+'</h4><div class=\"sub\">'+(e.meetTime?'Meet '+esc(e.meetTime)+' \u00b7 ':'')+esc(e.meetPoint||\"\")+'</div></div>'\n    + '<div class=\"count\"><b>'+c.cars+(c.cap?'/'+c.cap:'')+'</b>'+(t===\"social\"?'in':'cars')+'<br>'+c.chip+'</div>'\n    + '</button>';\n}\n\nfunction detailHTML(id){\n  const e = S.events.find(x => x.id === id);\n  if(!e) return '<button class=\"btn link back\" data-go=\"list\">\u2190 All events</button><p class=\"empty\">This event has been removed.</p>';\n  const t = typeOf(e), {going, waiting, cap} = split(e), me = mine(e), up = isUpcoming(e);\n  const pax = going.reduce((a,s) => a + (Number(s.people)||1), 0);\n  const kit = (e.kit||\"\").split(\"\\n\").map(s => s.trim()).filter(Boolean);\n  const bringing = going.concat(waiting).map(s => s.bringing).filter(Boolean);\n  let h = '<button class=\"btn link back\" data-go=\"list\">\u2190 All events</button>' + flashHTML();\n  h += '<div class=\"detail-head\"><span class=\"tag t-'+t+'\">'+esc(TYPES[t].label)+'</span><h2>'+esc(e.title)+'</h2>'\n    + '<div class=\"meta\"><span>'+esc(dateRange(e))+'</span><span class=\"chip\">'+(up?esc(whenChip(e)):'Past')+'</span>'+(e.organiser?'<span>Organised by <b>'+esc(e.organiser)+'</b></span>':'')+'</div></div>';\n\n  const facts = [];\n  if(e.meetTime) facts.push(['Meet at','<span class=\"mono\">'+esc(e.meetTime)+'</span>']);\n  if(e.meetPoint) facts.push(['Meeting point', esc(e.meetPoint) + (e.mapLink && /^https?:\\/\\//i.test(e.mapLink) ? ' \u00b7 <a href=\"'+esc(e.mapLink)+'\" target=\"_blank\" rel=\"noopener\">Map pin \u2197</a>' : '')]);\n  if(e.radio) facts.push(['Radio channel','<span class=\"mono\">'+esc(e.radio)+'</span>']);\n  if(e.destination) facts.push(['Heading to', esc(e.destination)]);\n  if(e.difficulty) facts.push(['Difficulty', esc(e.difficulty)]);\n  if(e.requirement) facts.push(['Vehicle / fitness', esc(e.requirement)]);\n  facts.push(['Signed up', '<span class=\"mono\">'+going.length+(cap?' of '+cap:'')+'</span> '+(t===\"social\"?'':'vehicles, ')+'<span class=\"mono\">'+pax+'</span> people'+(waiting.length?' \u00b7 '+waiting.length+' waiting':'')]);\n  h += '<div class=\"facts\">'+facts.map(f => '<div class=\"fact\"><span class=\"label\">'+f[0]+'</span><span class=\"v\">'+f[1]+'</span></div>').join(\"\")+'</div>';\n\n  if(e.details) h += '<p class=\"prose\">'+esc(e.details)+'</p>';\n  if(e.sponsorName) h += '<div class=\"sponsor\"><span class=\"label\">Sponsor</span><strong>'+esc(e.sponsorName)+'</strong>'+(e.sponsorOffer?'<span>'+esc(e.sponsorOffer)+'</span>':'')+'</div>';\n\n  h += '<div class=\"actions\">';\n  if(up){\n    h += me ? '<button class=\"btn\" data-join=\"'+esc(e.id)+'\">Change my details</button><button class=\"btn danger\" data-leave=\"'+esc(e.id)+'\">I can\\'t make it</button>'\n            : '<button class=\"btn primary\" data-join=\"'+esc(e.id)+'\">'+(cap && going.length >= cap ? 'Join the waitlist' : 'I\\'m in')+'</button>';\n  }\n  h += '<button class=\"btn\" data-copy=\"'+esc(e.id)+'\">Copy for WhatsApp</button>';\n  if(S.isOrg) h += '<button class=\"btn\" data-copylist=\"'+esc(e.id)+'\">Copy list with numbers</button><button class=\"btn link\" data-edit=\"'+esc(e.id)+'\">Edit event</button>';\n  h += '</div><div id=\"copyOut\"></div>';\n\n  if(kit.length) h += '<h2 class=\"section\">What to bring</h2><ul class=\"kit\">'+kit.map(k => '<li>'+esc(k)+'</li>').join(\"\")+'</ul>';\n  h += '<h2 class=\"section\">Who\\'s coming</h2>';\n  h += going.length ? '<div class=\"people\">'+going.map((s,i) => personHTML(s,i+1,false)).join(\"\")+'</div>' : '<p class=\"empty\">No one yet. Be the first.</p>';\n  if(waiting.length) h += '<h2 class=\"section\" style=\"font-size:18px\">Waitlist</h2><div class=\"people\">'+waiting.map((s,i) => personHTML(s,i+1,true)).join(\"\")+'</div>';\n  if(bringing.length) h += '<div style=\"margin-top:16px\"><span class=\"label\">Already covered</span><div class=\"bringing\">'+bringing.map(b => '<span>'+esc(b)+'</span>').join(\"\")+'</div></div>';\n  return h;\n}\n\nfunction personHTML(s, n, wait){\n  const bits = [s.vehicle, s.bringing ? 'Bringing '+s.bringing : '', s.note].filter(Boolean).map(esc).join(' \u00b7 ');\n  const tel = s.phone ? '<div class=\"tel\"><a href=\"tel:'+esc(s.phone)+'\">'+esc(fmtPhone(s.phone))+'</a></div>' : '';\n  return '<div class=\"person'+(wait?' wait':'')+'\"><span class=\"n\">'+String(n).padStart(2,\"0\")+'</span><div><div class=\"who\">'+esc(s.name)+(s.mine?' (you)':'')+'</div>'+(bits?'<div class=\"what\">'+bits+'</div>':'')+tel+'</div><span class=\"pax\">'+(Number(s.people)||1)+' pax</span></div>';\n}\n\nfunction joinHTML(id){\n  const e = S.events.find(x => x.id === id);\n  if(!e) return detailHTML(id);\n  const me = mine(e) || {}, t = typeOf(e);\n  const name = me.name || store.get(\"no_name\"), vehicle = me.vehicle || store.get(\"no_vehicle\"), phone = store.get(\"no_phone\");\n  return '<button class=\"btn link back\" data-go=\"detail\" data-id=\"'+esc(id)+'\">\u2190 Back to event</button>'\n    + '<div class=\"detail-head\"><span class=\"label\">'+esc(dateRange(e))+'</span><h2>'+esc(e.title)+'</h2></div>'\n    + '<form id=\"joinForm\" novalidate>'\n    + '<div class=\"two\"><div class=\"field\"><label for=\"j-name\">Your name</label><input id=\"j-name\" required maxlength=\"60\" value=\"'+esc(name)+'\" autocomplete=\"name\"></div>'\n    + '<div class=\"field\"><label for=\"j-phone\">Mobile number</label><input id=\"j-phone\" type=\"tel\" inputmode=\"tel\" required maxlength=\"20\" placeholder=\"050 123 4567\" value=\"'+esc(fmtPhone(phone))+'\" autocomplete=\"tel\"'+(me.eventId?' readonly':'')+'><span class=\"hint\">Only organisers see this, so we can call if you\\'re running late.</span></div></div>'\n    + '<div class=\"two\">'\n    + (t!==\"social\" ? '<div class=\"field\"><label for=\"j-vehicle\">Vehicle</label><input id=\"j-vehicle\" maxlength=\"60\" placeholder=\"e.g. Patrol Y62, Wrangler JL\" value=\"'+esc(vehicle)+'\"></div>' : '')\n    + '<div class=\"field\"><label for=\"j-people\">People '+(t!==\"social\"?'in your car':'coming')+'</label><input id=\"j-people\" type=\"number\" inputmode=\"numeric\" min=\"1\" max=\"12\" value=\"'+esc(me.people||1)+'\"></div>'\n    + '</div>'\n    + '<div class=\"field\"><label for=\"j-bring\">What you\\'re bringing to share</label><input id=\"j-bring\" maxlength=\"80\" placeholder=\"e.g. firewood, dessert, coffee kit\" value=\"'+esc(me.bringing||\"\")+'\"><span class=\"hint\">Shows on the event so we don\\'t end up with twelve bags of crisps.</span></div>'\n    + '<div class=\"field\"><label for=\"j-note\">Anything else</label><input id=\"j-note\" maxlength=\"120\" placeholder=\"e.g. first dune drive, happy to take a passenger\" value=\"'+esc(me.note||\"\")+'\"></div>'\n    + '<div id=\"j-err\" class=\"err\" role=\"alert\"></div>'\n    + '<div class=\"actions\"><button class=\"btn primary\" type=\"submit\" id=\"j-save\">'+(me.eventId?'Save changes':'Count me in')+'</button></div>'\n    + '</form>';\n}\n\nfunction whoHTML(){\n  return '<button class=\"btn link back\" data-go=\"list\">\u2190 All events</button>'\n    + '<div class=\"detail-head\"><h2>Who\\'s on this phone?</h2></div>'\n    + '<form id=\"whoForm\" novalidate>'\n    + '<p class=\"prose\" style=\"margin:0\">Enter the name and number you sign up with. This phone will remember you, and any events you\\'ve already joined will show as yours.</p>'\n    + '<div class=\"field\"><label for=\"w-name\">Your name</label><input id=\"w-name\" maxlength=\"60\" value=\"'+esc(store.get(\"no_name\"))+'\" autocomplete=\"name\"></div>'\n    + '<div class=\"field\"><label for=\"w-phone\">Mobile number</label><input id=\"w-phone\" type=\"tel\" inputmode=\"tel\" maxlength=\"20\" placeholder=\"050 123 4567\" value=\"'+esc(fmtPhone(store.get(\"no_phone\")))+'\" autocomplete=\"tel\"></div>'\n    + '<div id=\"w-err\" class=\"err\" role=\"alert\"></div>'\n    + '<div class=\"actions\"><button class=\"btn primary\" type=\"submit\">Save</button>'+(store.get(\"no_phone\")?'<button class=\"btn link\" type=\"button\" data-forget>Forget me on this phone</button>':'')+'</div>'\n    + '</form>';\n}\n\nfunction orgHTML(){\n  return '<button class=\"btn link back\" data-go=\"list\">\u2190 All events</button>'\n    + '<div class=\"detail-head\"><h2>Organiser login</h2></div>'\n    + '<form id=\"orgForm\" novalidate>'\n    + '<p class=\"prose\" style=\"margin:0\">Organisers can post and edit events and see members\\' numbers. Ask Richard for the code.</p>'\n    + '<div class=\"field\"><label for=\"o-code\">Organiser code</label><input id=\"o-code\" type=\"password\" autocomplete=\"current-password\" maxlength=\"80\"></div>'\n    + '<div id=\"o-err\" class=\"err\" role=\"alert\"></div>'\n    + '<div class=\"actions\"><button class=\"btn primary\" type=\"submit\" id=\"o-save\">Log in</button></div>'\n    + '</form>';\n}\n\nfunction editHTML(id){\n  const e = id ? (S.events.find(x => x.id === id) || {}) : {type:\"desert\", kit:TYPES.desert.kit, difficulty:\"Moderate\", organiser:store.get(\"no_name\")};\n  const opt = (val, lab, cur) => '<option value=\"'+esc(val)+'\"'+(val===cur?' selected':'')+'>'+esc(lab)+'</option>';\n  const f = (fid, lab, val, extra='', hint='') => '<div class=\"field\"><label for=\"'+fid+'\">'+lab+'</label><input id=\"'+fid+'\" value=\"'+esc(val||\"\")+'\" '+extra+'>'+(hint?'<span class=\"hint\">'+hint+'</span>':'')+'</div>';\n  return '<button class=\"btn link back\" data-go=\"'+(id?'detail':'list')+'\" data-id=\"'+esc(id||\"\")+'\">\u2190 '+(id?'Back to event':'All events')+'</button>'\n    + '<div class=\"detail-head\"><h2>'+(id?'Edit event':'Post an event')+'</h2></div>'\n    + '<form id=\"editForm\" novalidate>'\n    + f(\"e-title\",\"Event name\",e.title,'required maxlength=\"70\" placeholder=\"e.g. Big Red sunset run\"')\n    + '<div class=\"two\"><div class=\"field\"><label for=\"e-type\">Type</label><select id=\"e-type\">'+Object.entries(TYPES).map(([k,v]) => opt(k,v.label,e.type)).join(\"\")+'</select></div>'\n    + '<div class=\"field\"><label for=\"e-diff\">Difficulty</label><select id=\"e-diff\">'+opt(\"\",\"Not relevant\",e.difficulty||\"\")+DIFF.map(d => opt(d,d,e.difficulty)).join(\"\")+'</select></div></div>'\n    + '<div class=\"two\">'+f(\"e-date\",\"Date\",e.date,'type=\"date\" required')+f(\"e-end\",\"Ends (overnight trips)\",e.endDate,'type=\"date\"')+'</div>'\n    + '<div class=\"two\">'+f(\"e-time\",\"Meet time\",e.meetTime,'type=\"time\"')+f(\"e-cap\",\"Max vehicles\",e.capacity||\"\",'type=\"number\" inputmode=\"numeric\" min=\"1\" max=\"60\" placeholder=\"No limit\"','Extra sign-ups go on a waitlist.')+'</div>'\n    + f(\"e-meet\",\"Meeting point\",e.meetPoint,'maxlength=\"90\" placeholder=\"e.g. ADNOC Al Qudra Rd, by the air pumps\"')\n    + '<div class=\"two\">'+f(\"e-map\",\"Map pin link\",e.mapLink,'type=\"url\" placeholder=\"Paste a Google Maps link\"')+f(\"e-radio\",\"Radio channel\",e.radio,'maxlength=\"40\" placeholder=\"e.g. PMR 3, CTCSS 12\"','Tune in before you arrive.')+'</div>'\n    + f(\"e-dest\",\"Heading to\",e.destination,'maxlength=\"90\" placeholder=\"e.g. Fossil Rock, Hatta, Liwa\"')\n    + f(\"e-req\",\"Vehicle or fitness requirement\",e.requirement,'maxlength=\"90\" placeholder=\"e.g. 4x4 with low range, aired down to 15 psi\"')\n    + f(\"e-org\",\"Organised by\",e.organiser,'maxlength=\"60\"')\n    + '<div class=\"field\"><label for=\"e-details\">Details</label><textarea id=\"e-details\" maxlength=\"1500\" placeholder=\"Route, plan for the day, anything people should know\">'+esc(e.details||\"\")+'</textarea></div>'\n    + '<div class=\"field\"><label for=\"e-kit\">What to bring</label><textarea id=\"e-kit\" maxlength=\"1200\">'+esc(e.kit||\"\")+'</textarea><span class=\"hint\">One item per line. Changing the type fills in a starter list.</span></div>'\n    + '<fieldset><legend>Sponsor (optional)</legend>'+f(\"e-spn\",\"Sponsor\",e.sponsorName,'maxlength=\"60\" placeholder=\"Company or person\"')+f(\"e-spo\",\"What they\\'re offering the group\",e.sponsorOffer,'maxlength=\"160\" placeholder=\"e.g. a new recovery kit to one member after the drive\"')+'</fieldset>'\n    + '<div id=\"e-err\" class=\"err\" role=\"alert\"></div>'\n    + '<div class=\"actions\"><button class=\"btn primary\" type=\"submit\" id=\"e-save\">'+(id?'Save changes':'Post to the board')+'</button>'\n    + (id ? '<span id=\"delZone\"><button type=\"button\" class=\"btn link\" data-del>Delete event</button></span>' : '')\n    + '</div></form>';\n}\n\n/* ---------- wiring ---------- */\nfunction wireEdit(id){\n  const type = $(\"#e-type\"), kit = $(\"#e-kit\");\n  type.addEventListener(\"change\", () => {\n    const cur = kit.value.trim();\n    if(!cur || Object.values(TYPES).some(t => t.kit === cur)) kit.value = TYPES[type.value].kit;\n  });\n  $(\"#editForm\").addEventListener(\"submit\", async ev => {\n    ev.preventDefault();\n    const val = s => $(s).value.trim(), err = $(\"#e-err\"); err.textContent = \"\";\n    const data = {\n      id, title:val(\"#e-title\"), type:type.value, difficulty:val(\"#e-diff\"), date:val(\"#e-date\"), endDate:val(\"#e-end\"),\n      meetTime:val(\"#e-time\"), capacity:val(\"#e-cap\") ? Number(val(\"#e-cap\")) : 0, meetPoint:val(\"#e-meet\"), mapLink:val(\"#e-map\"),\n      radio:val(\"#e-radio\"), destination:val(\"#e-dest\"), requirement:val(\"#e-req\"), organiser:val(\"#e-org\"),\n      details:$(\"#e-details\").value.trim(), kit:kit.value.trim(), sponsorName:val(\"#e-spn\"), sponsorOffer:val(\"#e-spo\")\n    };\n    if(!data.title){ err.textContent = \"Give the event a name.\"; $(\"#e-title\").focus(); return; }\n    if(!data.date){ err.textContent = \"Pick a date.\"; $(\"#e-date\").focus(); return; }\n    if(data.endDate && data.endDate < data.date){ err.textContent = \"The end date is before the start date.\"; return; }\n    if(data.mapLink && !/^https?:\\/\\//i.test(data.mapLink)){ err.textContent = \"The map link should start with https://\"; return; }\n    $(\"#e-save\").disabled = true;\n    try{\n      const r = await api(\"/events\", data);\n      if(!id && data.organiser && !store.get(\"no_name\")) store.set(\"no_name\", data.organiser);\n      S.flash = id ? \"Changes saved.\" : \"Posted. Tap Copy for WhatsApp to tell the group.\";\n      await load(); go({name:\"detail\", id:r.id});\n    }catch(e){ err.textContent = e.message; $(\"#e-save\").disabled = false; }\n  });\n}\n\nfunction wireJoin(id){\n  $(\"#joinForm\").addEventListener(\"submit\", async ev => {\n    ev.preventDefault();\n    const err = $(\"#j-err\"); err.textContent = \"\";\n    const name = $(\"#j-name\").value.trim(), phone = $(\"#j-phone\").value.trim();\n    if(!name){ err.textContent = \"Add your name so people know who's coming.\"; $(\"#j-name\").focus(); return; }\n    if(phone.replace(/\\D/g,\"\").length < 8){ err.textContent = \"Add your mobile number so we can reach you on the day.\"; $(\"#j-phone\").focus(); return; }\n    const vehicle = $(\"#j-vehicle\") ? $(\"#j-vehicle\").value.trim() : \"\";\n    const wasIn = !!mine(S.events.find(x => x.id === id) || {id});\n    $(\"#j-save\").disabled = true;\n    try{\n      const r = await api(\"/signup\", {eventId:id, name, phone, vehicle, people:Number($(\"#j-people\").value)||1, bringing:$(\"#j-bring\").value.trim(), note:$(\"#j-note\").value.trim()});\n      store.set(\"no_name\", name); store.set(\"no_phone\", r.phone); if(vehicle) store.set(\"no_vehicle\", vehicle);\n      S.flash = wasIn ? \"Your details are updated.\" : (r.waitlisted ? \"The event is full, so you're on the waitlist. We'll shout if a space opens.\" : \"You're on the list. See you there.\");\n      S.view = {name:\"detail\", id}; await load(); window.scrollTo(0,0);\n    }catch(e){ err.textContent = e.message; $(\"#j-save\").disabled = false; }\n  });\n}\n\nfunction wireWho(){\n  $(\"#whoForm\").addEventListener(\"submit\", async ev => {\n    ev.preventDefault();\n    const err = $(\"#w-err\"); err.textContent = \"\";\n    const name = $(\"#w-name\").value.trim(), phone = $(\"#w-phone\").value.trim();\n    if(phone.replace(/\\D/g,\"\").length < 8){ err.textContent = \"That number looks too short.\"; return; }\n    try{\n      const r = await api(\"/phone\", {phone});\n      store.set(\"no_name\", name); store.set(\"no_phone\", r.phone);\n      S.flash = \"Saved. This phone now knows who you are.\"; S.view = {name:\"list\"}; await load();\n    }catch(e){ err.textContent = e.message; }\n  });\n}\n\nfunction wireOrg(){\n  $(\"#orgForm\").addEventListener(\"submit\", async ev => {\n    ev.preventDefault();\n    const err = $(\"#o-err\"), code = $(\"#o-code\").value.trim(); err.textContent = \"\";\n    if(!code) return;\n    $(\"#o-save\").disabled = true;\n    try{\n      await api(\"/organiser\", {code});\n      store.set(\"no_org\", code); S.flash = \"Organiser mode is on. You can post events and see numbers.\";\n      S.view = {name:\"list\"}; await load();\n    }catch(e){ err.textContent = e.message; $(\"#o-save\").disabled = false; }\n  });\n}\n\nfunction whatsappText(e){\n  const {going, cap} = split(e), t = typeOf(e);\n  const kit = (e.kit||\"\").split(\"\\n\").map(s => s.trim()).filter(Boolean);\n  const lines = [\"*\"+e.title+\"*\", TYPES[t].label+(e.difficulty?\" \u00b7 \"+e.difficulty:\"\"), \"\ud83d\udcc5 \"+dateRange(e)+(e.meetTime?\" \u00b7 meet \"+e.meetTime:\"\")];\n  if(e.meetPoint) lines.push(\"\ud83d\udccd \"+e.meetPoint);\n  if(e.mapLink) lines.push(e.mapLink);\n  if(e.radio) lines.push(\"\ud83d\udcfb Radio: \"+e.radio);\n  if(e.destination) lines.push(\"\u27a1\ufe0f \"+e.destination);\n  if(e.requirement) lines.push(\"\ud83d\ude99 \"+e.requirement);\n  if(e.sponsorName) lines.push(\"\ud83c\udf81 Supported by \"+e.sponsorName+(e.sponsorOffer?\": \"+e.sponsorOffer:\"\"));\n  lines.push(\"\", (t===\"social\"?\"Signed up: \":\"Vehicles in: \")+going.length+(cap?\"/\"+cap:\"\"));\n  if(going.length) lines.push(going.map(s => s.name).join(\", \"));\n  if(kit.length) lines.push(\"\", \"Bring: \"+kit.join(\", \"));\n  lines.push(\"\", \"Sign up here: \"+location.origin+\"/board\");\n  return lines.join(\"\\n\");\n}\nfunction listText(e){\n  const {going, waiting} = split(e);\n  const row = (s,i) => (i+1)+\". \"+s.name+\" \u00b7 \"+fmtPhone(s.phone)+(s.vehicle?\" \u00b7 \"+s.vehicle:\"\")+\" \u00b7 \"+(s.people||1)+\" pax\";\n  let t = e.title+\" (\"+dateRange(e)+\")\\n\\n\"+going.map(row).join(\"\\n\");\n  if(waiting.length) t += \"\\n\\nWaitlist\\n\"+waiting.map(row).join(\"\\n\");\n  return t;\n}\nasync function copyText(btn, text){\n  const label = btn.textContent;\n  try{ await navigator.clipboard.writeText(text); btn.textContent = \"Copied \u2713\"; setTimeout(() => { btn.textContent = label; }, 2000); }\n  catch(_){\n    $(\"#copyOut\").innerHTML = '<div class=\"field\" style=\"margin-bottom:16px\"><label for=\"wa-text\">Copy this text</label><textarea id=\"wa-text\" rows=\"10\" readonly></textarea></div>';\n    const ta = $(\"#wa-text\"); ta.value = text; ta.focus(); ta.select();\n  }\n}\n\ndocument.addEventListener(\"click\", async ev => {\n  const b = ev.target.closest(\"button\"); if(!b) return;\n  if(b.id === \"newBtn\") return go({name:\"edit\", id:null});\n  if(b.dataset.open) return go({name:\"detail\", id:b.dataset.open});\n  if(b.dataset.go) return go(b.dataset.id ? {name:b.dataset.go, id:b.dataset.id} : {name: b.dataset.go === \"detail\" ? \"list\" : b.dataset.go});\n  if(b.dataset.join) return go({name:\"join\", id:b.dataset.join});\n  if(b.dataset.edit) return go({name:\"edit\", id:b.dataset.edit});\n  if(b.dataset.copy){ const e = S.events.find(x => x.id === b.dataset.copy); if(e) copyText(b, whatsappText(e)); return; }\n  if(b.dataset.copylist){ const e = S.events.find(x => x.id === b.dataset.copylist); if(e) copyText(b, listText(e)); return; }\n  if(b.dataset.leave){\n    b.disabled = true;\n    try{ await api(\"/cancel\", {eventId:b.dataset.leave, phone:store.get(\"no_phone\")}); S.flash = \"You're off the list. Maybe next time.\"; await load(); }\n    catch(e){ b.disabled = false; S.flash = e.message; render(); }\n    return;\n  }\n  if(b.hasAttribute(\"data-forget\")){ store.set(\"no_phone\",\"\"); store.set(\"no_name\",\"\"); store.set(\"no_vehicle\",\"\"); S.flash = \"This phone has forgotten you.\"; S.view = {name:\"list\"}; await load(); return; }\n  if(b.hasAttribute(\"data-orgout\")){ store.set(\"no_org\",\"\"); S.isOrg = false; S.flash = \"Organiser mode is off.\"; go({name:\"list\"}); load(); return; }\n  if(b.hasAttribute(\"data-del\")){ $(\"#delZone\").innerHTML = '<span class=\"confirm\">Delete this event and its sign-ups? <button type=\"button\" class=\"btn danger small\" data-delyes>Delete</button><button type=\"button\" class=\"btn link\" data-delno>Keep it</button></span>'; return; }\n  if(b.hasAttribute(\"data-delno\")){ $(\"#delZone\").innerHTML = '<button type=\"button\" class=\"btn link\" data-del>Delete event</button>'; return; }\n  if(b.hasAttribute(\"data-delyes\")){\n    b.disabled = true;\n    try{ await api(\"/events/delete\", {id:S.view.id}); S.flash = \"Event deleted.\"; S.view = {name:\"list\"}; await load(); window.scrollTo(0,0); }\n    catch(e){ b.disabled = false; $(\"#e-err\").textContent = e.message; }\n  }\n});\n\nsetInterval(() => { if(document.visibilityState === \"visible\" && !inForm()) load(); }, 30000);\ndocument.addEventListener(\"visibilitychange\", () => { if(document.visibilityState === \"visible\" && !inForm()) load(); });\nrender();\nload();\n</script>\n</body>\n</html>\n";
const HOME = "<!doctype html>\n<html lang=\"en-GB\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1,viewport-fit=cover\">\n<title>Nomad Outdoors</title>\n<meta name=\"description\" content=\"A small, invitation-only group in the UAE heading out most weekends for dune drives, wadi trips, overland routes and nights under the stars.\">\n<link rel=\"canonical\" href=\"__ORIGIN__/\">\n<meta property=\"og:url\" content=\"__ORIGIN__/\">\n<meta property=\"og:site_name\" content=\"Nomad Outdoors\">\n<meta property=\"og:title\" content=\"Nomad Outdoors\">\n<meta property=\"og:description\" content=\"Dune drives, wadi trips, overland routes and nights under the stars across the UAE.\">\n<meta property=\"og:type\" content=\"website\">\n<meta property=\"og:image\" content=\"__ORIGIN__/og-image.png\">\n<meta property=\"og:image:width\" content=\"1200\">\n<meta property=\"og:image:height\" content=\"630\">\n<meta property=\"og:image:alt\" content=\"Nomad Outdoors: drives, wadis, camps and campfires\">\n<meta name=\"twitter:card\" content=\"summary_large_image\">\n<meta name=\"theme-color\" content=\"#17201E\">\n<link rel=\"manifest\" href=\"/manifest.webmanifest\">\n<link rel=\"apple-touch-icon\" href=\"/apple-touch-icon.png\">\n<link rel=\"icon\" href=\"/icon-192.png\">\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n<link rel=\"stylesheet\" href=\"https://fonts.googleapis.com/css2?family=Big+Shoulders+Display:wght@600;800&family=Public+Sans:wght@400;500;600;700&family=IBM+Plex+Mono:wght@500&display=swap\">\n<style>\n:root{\n  --bg:#EDF0EC;--surface:#FFFFFF;--surface-2:#E3E8E3;--ink:#17201E;--muted:#586562;--line:#D0D8D3;\n  --accent:#0E6B62;--accent-ink:#FFFFFF;--amber:#A86F00;\n  --night:#17201E;--night-ink:#EDF0EC;--night-muted:#9AA9A5;--sun:#4DB6A9;--dune-1:#B86E00;--dune-2:#EBA43A;\n  --t-desert:#B86E00;--t-wadi:#17758A;--t-camping:#4A7628;--t-overland:#8A4A28;--t-social:#7A3E78;\n  --display:\"Big Shoulders Display\",\"Arial Narrow\",Impact,sans-serif;\n  --body:\"Public Sans\",system-ui,-apple-system,\"Segoe UI\",sans-serif;\n  --mono:\"IBM Plex Mono\",ui-monospace,Menlo,Consolas,monospace;\n}\n@media (prefers-color-scheme: dark){\n  :root{\n    color-scheme:dark;\n    --bg:#101615;--surface:#18201F;--surface-2:#212B29;--ink:#E5ECE9;--muted:#9AA9A5;--line:#2D3936;\n    --accent:#4DB6A9;--accent-ink:#0A1211;--amber:#F0B93A;\n    --t-desert:#EBA43A;--t-wadi:#5CC0D4;--t-camping:#93C466;--t-overland:#D98E66;--t-social:#D08ACD;\n  }\n}\n*{box-sizing:border-box}\nhtml{-webkit-text-size-adjust:100%;scroll-behavior:smooth}\n@media (prefers-reduced-motion:reduce){html{scroll-behavior:auto}}\nbody{margin:0;background:var(--bg);color:var(--ink);font-family:var(--body);font-size:16px;line-height:1.6}\na{color:var(--accent);text-underline-offset:3px}\n:focus-visible{outline:2px solid var(--accent);outline-offset:3px}\n.in{max-width:1040px;margin:0 auto;padding-inline:20px}\n\n/* night hero */\n.hero{background:var(--night);color:var(--night-ink);position:relative;overflow:hidden;padding-top:env(safe-area-inset-top,0px)}\n.nav{display:flex;align-items:center;justify-content:space-between;gap:16px;padding-block:18px;flex-wrap:wrap}\n.nav .mark{font-family:var(--display);font-weight:800;font-size:22px;letter-spacing:.04em;text-transform:uppercase;color:var(--night-ink);text-decoration:none}\n.nav ul{list-style:none;margin:0;padding:0;display:flex;gap:22px;flex-wrap:wrap;align-items:center;font-size:14px;font-weight:600}\n.nav ul a{color:var(--night-muted);text-decoration:none}\n.nav ul a:hover{color:var(--night-ink)}\n.nav .board{color:var(--night);background:var(--dune-2);padding:7px 14px;border-radius:6px}\n.nav .board:hover{color:var(--night);filter:brightness(1.08)}\n.hero-body{position:relative;z-index:2;padding-block:56px 200px}\n.hero h1{font-family:var(--display);font-weight:800;font-size:clamp(68px,13vw,148px);line-height:.86;text-transform:uppercase;margin:0;letter-spacing:.005em}\n.hero .lede{max-width:34em;font-size:clamp(17px,2.2vw,20px);color:var(--night-muted);margin:24px 0 0}\n.next{display:inline-flex;flex-wrap:wrap;align-items:baseline;gap:6px 14px;margin-top:28px;padding:12px 16px;border:1px solid rgba(237,240,236,.22);border-radius:8px;font-size:15px;color:var(--night-ink);text-decoration:none}\n.next:hover{border-color:var(--dune-2)}\n.next .k{font-size:11px;letter-spacing:.14em;text-transform:uppercase;font-weight:700;color:var(--dune-2)}\n.next .d{font-family:var(--mono);font-size:14px}\n.sun{position:absolute;right:9%;top:88px;width:clamp(90px,14vw,150px);aspect-ratio:1;border-radius:50%;background:var(--sun);z-index:1}\n.dunes{position:absolute;left:0;right:0;bottom:-1px;width:100%;height:190px;z-index:1;display:block}\n\n/* sections */\nsection{padding-block:72px}\n.eyebrow{font-size:12px;letter-spacing:.14em;text-transform:uppercase;font-weight:700;color:var(--amber);margin:0 0 10px}\nh2{font-family:var(--display);font-weight:800;font-size:clamp(38px,6vw,56px);line-height:.95;text-transform:uppercase;margin:0 0 20px;text-wrap:balance}\nh3{font-size:18px;margin:0 0 6px}\np{margin:0 0 14px;max-width:65ch}\n.split{display:grid;grid-template-columns:1fr 1fr;gap:48px;align-items:start}\n.rules{display:grid;gap:22px;margin:0;padding:0;list-style:none}\n.rules li{border-top:2px solid var(--ink);padding-top:12px}\n.rules p{color:var(--muted);margin:0}\n\n.types{display:grid;grid-template-columns:repeat(auto-fit,minmax(190px,1fr));gap:1px;background:var(--line);border:1px solid var(--line);border-radius:10px;overflow:hidden;margin-top:28px}\n.type{background:var(--surface);padding:20px;display:flex;flex-direction:column;gap:8px}\n.type p{margin:0;color:var(--muted);font-size:15px}\n.tag{display:inline-flex;align-items:center;gap:7px;font-size:12px;font-weight:700;letter-spacing:.06em;text-transform:uppercase;color:var(--tc)}\n.tag::before{content:\"\";width:9px;height:9px;border-radius:2px;background:var(--tc)}\n.t-desert{--tc:var(--t-desert)}.t-wadi{--tc:var(--t-wadi)}.t-camping{--tc:var(--t-camping)}.t-overland{--tc:var(--t-overland)}.t-social{--tc:var(--t-social)}\n\n.log{margin-top:24px;border-top:1px solid var(--line)}\n.log-row{display:grid;grid-template-columns:120px 1fr auto;gap:16px;align-items:baseline;padding:12px 0;border-bottom:1px solid var(--line)}\n.log-row .when{font-family:var(--mono);font-size:14px;color:var(--muted);font-variant-numeric:tabular-nums}\n.log-row .what{font-weight:600}\n.log-row .n{font-size:14px;color:var(--muted);white-space:nowrap}\n\n.band{background:var(--surface);border-block:1px solid var(--line)}\n.steps{display:grid;grid-template-columns:repeat(3,1fr);gap:28px;margin:28px 0 32px;padding:0;list-style:none;counter-reset:s}\n.steps li{counter-increment:s}\n.steps li::before{content:counter(s);display:block;font-family:var(--display);font-weight:800;font-size:44px;line-height:1;color:var(--amber);margin-bottom:8px}\n.steps p{color:var(--muted);font-size:15px;margin:0}\n.contact{display:flex;flex-wrap:wrap;align-items:center;gap:12px 20px}\n.btn{display:inline-flex;align-items:center;gap:8px;background:var(--accent);color:var(--accent-ink);text-decoration:none;font-weight:700;padding:11px 18px;border-radius:6px}\n.btn:hover{filter:brightness(1.08)}\n.mail{font-family:var(--mono);font-size:15px;color:var(--ink)}\n\n.garage{display:grid;grid-template-columns:repeat(2,1fr);gap:20px;margin-top:24px}\n.garage article{border:1px solid var(--line);border-radius:10px;padding:22px;background:var(--surface)}\n.garage article p{color:var(--muted);font-size:15px}\n.garage article p:last-child{margin:0}\n.garage .for{font-size:12px;letter-spacing:.08em;text-transform:uppercase;font-weight:700;color:var(--muted);margin-bottom:8px}\n\nfooter{background:var(--night);color:var(--night-muted);font-size:14px;padding-block:32px calc(32px + env(safe-area-inset-bottom,0px))}\nfooter .in{display:flex;flex-wrap:wrap;justify-content:space-between;gap:12px}\nfooter a{color:var(--night-ink)}\n\n@media (max-width:760px){\n  .split,.garage,.steps{grid-template-columns:1fr}\n  .split{gap:28px}\n  section{padding-block:52px}\n  .hero-body{padding-block:36px 150px}\n  .dunes{height:140px}\n  .sun{display:none}\n  .nav ul{gap:14px}\n  .nav ul li.opt{display:none}\n  .log-row{grid-template-columns:1fr auto}\n  .log-row .when{grid-column:1/-1}\n}\n</style>\n</head>\n<body>\n\n<header class=\"hero\">\n  <div class=\"in\">\n    <nav class=\"nav\" aria-label=\"Main\">\n      <a class=\"mark\" href=\"/\">Nomad Outdoors</a>\n      <ul>\n        <li class=\"opt\"><a href=\"#how\">How we roll</a></li>\n        <li class=\"opt\"><a href=\"#partners\">Kit partners</a></li>\n        <li class=\"opt\"><a href=\"#garage\">The garage</a></li>\n        <li><a class=\"board\" href=\"/board\">Event board</a></li>\n      </ul>\n    </nav>\n    <div class=\"hero-body\">\n      <h1>Out past<br>the tarmac</h1>\n      <p class=\"lede\">Nomad Outdoors is a small, invitation-only group in the UAE. Most weekends we head out together for dune drives, wadi trips, overland routes and nights under the stars.</p>\n      <a class=\"next\" id=\"next\" href=\"/board\" hidden></a>\n    </div>\n  </div>\n  <div class=\"sun\" aria-hidden=\"true\"></div>\n  <svg class=\"dunes\" viewBox=\"0 0 1200 190\" preserveAspectRatio=\"none\" aria-hidden=\"true\">\n    <path d=\"M0 110 L220 50 L480 95 L745 20 L1010 70 L1200 40 L1200 190 L0 190 Z\" fill=\"#B86E00\"/>\n    <path d=\"M0 165 L310 95 L625 160 L915 110 L1200 150 L1200 190 L0 190 Z\" fill=\"#EBA43A\"/>\n  </svg>\n</header>\n\n<main>\n  <section id=\"how\">\n    <div class=\"in split\">\n      <div>\n        <p class=\"eyebrow\">How we roll</p>\n        <h2>Friends first, convoy second</h2>\n        <p>We started as a handful of people who wanted to get out of the city more often. It still works the same way. Someone picks a route, posts it on the board and whoever can make it turns up at the meeting point with a full tank and something to share.</p>\n        <p>There's no fee, no committee and no one gets paid. When we run skills sessions, like recovery basics or navigating without signal, they're free for members too.</p>\n      </div>\n      <ul class=\"rules\">\n        <li><h3>Everyone brings something</h3><p>Firewood, coffee, dinner for the pot. The event board shows what's covered so nobody doubles up.</p></li>\n        <li><h3>Small by design</h3><p>We keep convoys to a size where everyone knows each other's name and nobody gets left in a bowl.</p></li>\n        <li><h3>Leave nothing behind</h3><p>What comes out with us goes home with us. Every camp site is left cleaner than we found it.</p></li>\n      </ul>\n    </div>\n  </section>\n\n  <section class=\"band\" id=\"trips\">\n    <div class=\"in\">\n      <p class=\"eyebrow\">What we do</p>\n      <h2>Five ways to spend a weekend</h2>\n      <div class=\"types\">\n        <div class=\"type\"><span class=\"tag t-desert\">Desert drives</span><p>Dune runs from easy warm-ups to big-bowl days, aired down with recovery gear ready.</p></div>\n        <div class=\"type\"><span class=\"tag t-wadi\">Wadi trips</span><p>Hajar mountain tracks, rock pools and the kind of shade you only find at the bottom of a gorge.</p></div>\n        <div class=\"type\"><span class=\"tag t-camping\">Camping</span><p>Overnights in the sand with a shared fire, too much food and a very clear sky.</p></div>\n        <div class=\"type\"><span class=\"tag t-overland\">Overlanding</span><p>Longer routes that link places together, planned around fuel, water and daylight.</p></div>\n        <div class=\"type\"><span class=\"tag t-social\">Socials</span><p>The occasional evening in town, mostly to plan the next trip.</p></div>\n      </div>\n      <div id=\"recent\" hidden>\n        <h3 style=\"margin-top:40px\">Recent trips</h3>\n        <div class=\"log\" id=\"log\"></div>\n      </div>\n    </div>\n  </section>\n\n  <section id=\"partners\">\n    <div class=\"in split\">\n      <div>\n        <p class=\"eyebrow\">Kit partners</p>\n        <h2>Try it where it matters</h2>\n        <p>If you make or sell outdoor, recovery or camping gear, we'd like to put it to work. We take new kit out on real trips in UAE heat and sand, tell you honestly how it performed, and share photos you're welcome to use.</p>\n        <p>Afterwards the kit stays with one of our members, so it keeps getting used by someone who'll talk about it around the next fire. The whole group benefits, and nobody at Nomad Outdoors takes a cut.</p>\n      </div>\n      <div>\n        <ol class=\"steps\" style=\"grid-template-columns:1fr;margin-top:0\">\n          <li><h3>You send us kit</h3><p>Tell us what it is and what you'd like to learn about it.</p></li>\n          <li><h3>We use it properly</h3><p>On a drive or a camp, in the conditions it was built for.</p></li>\n          <li><h3>You get the story</h3><p>An honest write-up and photos, and the kit goes to a member.</p></li>\n        </ol>\n        <div class=\"contact\">\n          <a class=\"btn\" href=\"mailto:hello@nomadoutdoors.org?subject=Kit%20partner\">Get in touch</a>\n          <span class=\"mail\">hello@nomadoutdoors.org</span>\n        </div>\n      </div>\n    </div>\n  </section>\n\n  <section class=\"band\" id=\"garage\">\n    <div class=\"in\">\n      <p class=\"eyebrow\">The garage</p>\n      <h2>Keeping older rigs running</h2>\n      <p>Plenty of us drive older 4x4s, and a thirty-year-old truck in forty-five-degree heat needs looking after. Two local resources our members lean on:</p>\n      <div class=\"garage\">\n        <article>\n          <p class=\"for\">For GMT400 Chevys and GMCs</p>\n          <h3><a href=\"https://obs-uae.com/\">OBS Icons UAE</a></h3>\n          <p>A free field guide to keeping 1988 to 1999 GM trucks and SUVs running in the Gulf. It covers cooling, electrics, drivetrain and off-road prep, with UAE part numbers and where to find them in Sharjah and Dubai.</p>\n        </article>\n        <article>\n          <p class=\"for\">For hard-to-find parts</p>\n          <h3><a href=\"https://obscureparts.com/\">OBScure Parts</a></h3>\n          <p>Specialist sourcing for GMT400 trucks, classic Land Rover Defenders and the Mercedes SL R107. Useful when the part you need hasn't been on a shelf in the UAE for twenty years.</p>\n        </article>\n      </div>\n    </div>\n  </section>\n\n  <section id=\"join\">\n    <div class=\"in split\">\n      <div>\n        <p class=\"eyebrow\">Joining</p>\n        <h2>By invitation</h2>\n      </div>\n      <div>\n        <p>We keep the group small so trips stay safe and friendly. New members join through someone who's already been out with us. If you know a member, ask them to bring you along on the next easy drive.</p>\n        <p>Already a member? Everything you need for the next trip is on the <a href=\"/board\">event board</a>.</p>\n      </div>\n    </div>\n  </section>\n</main>\n\n<footer>\n  <div class=\"in\">\n    <span>Nomad Outdoors \u00b7 UAE</span>\n    <span><a href=\"/board\">Event board</a> \u00b7 <a href=\"mailto:hello@nomadoutdoors.org\">hello@nomadoutdoors.org</a></span>\n  </div>\n</footer>\n\n<script>\n(async () => {\n  const LABEL = {desert:\"Desert drive\", wadi:\"Wadi trip\", camping:\"Camping\", overland:\"Overlanding\", social:\"Social\"};\n  const esc = v => String(v ?? \"\").replace(/[&<>\"']/g, c => ({\"&\":\"&amp;\",\"<\":\"&lt;\",\">\":\"&gt;\",'\"':\"&quot;\",\"'\":\"&#39;\"}[c]));\n  const parse = iso => { const [y,m,d] = iso.split(\"-\").map(Number); return new Date(y,m-1,d); };\n  const fmt = (iso, o) => parse(iso).toLocaleDateString(\"en-GB\", o);\n  const d = new Date(); d.setMinutes(d.getMinutes() - d.getTimezoneOffset()); const today = d.toISOString().slice(0,10);\n  try{\n    const res = await fetch(\"/api/board\", {cache:\"no-store\"});\n    if(!res.ok) return;\n    const {events, signups} = await res.json();\n    const count = id => signups.filter(s => s.eventId === id).length;\n    const up = events.filter(e => (e.endDate || e.date) >= today).sort((a,b) => a.date.localeCompare(b.date));\n    if(up.length){\n      const e = up[0], n = document.getElementById(\"next\");\n      n.innerHTML = '<span class=\"k\">Next trip</span><span class=\"d\">'+esc(fmt(e.date,{weekday:\"short\",day:\"numeric\",month:\"short\"}))+'</span><span>'+esc(LABEL[e.type]||\"Trip\")+': '+esc(e.title)+'</span>';\n      n.hidden = false;\n    }\n    const past = events.filter(e => (e.endDate || e.date) < today).sort((a,b) => b.date.localeCompare(a.date)).slice(0,6);\n    if(past.length){\n      document.getElementById(\"log\").innerHTML = past.map(e => {\n        const c = count(e.id), t = LABEL[e.type] ? e.type : \"social\";\n        return '<div class=\"log-row\"><span class=\"when\">'+esc(fmt(e.date,{day:\"numeric\",month:\"short\",year:\"numeric\"}))+'</span><span><span class=\"tag t-'+t+'\">'+esc(LABEL[t])+'</span> <span class=\"what\">'+esc(e.title)+'</span></span><span class=\"n\">'+(c ? c+(t===\"social\"?\" came\":\" vehicles\") : \"\")+'</span></div>';\n      }).join(\"\");\n      document.getElementById(\"recent\").hidden = false;\n    }\n  }catch(_){}\n})();\n</script>\n</body>\n</html>\n";
const ICONS = {"i180": "", "i192": "", "i512": "", "og": ""};

const MANIFEST = JSON.stringify({
  name: "Nomad Outdoors",
  short_name: "Nomad",
  start_url: "/board",
  display: "standalone",
  background_color: "#EDF0EC",
  theme_color: "#17201E",
  icons: [
    { src: "/icon-192.png", sizes: "192x192", type: "image/png" },
    { src: "/icon-512.png", sizes: "512x512", type: "image/png" },
    { src: "/icon-512.png", sizes: "512x512", type: "image/png", purpose: "maskable" }
  ]
});

const EVENT_FIELDS = {
  title: 70, type: 20, difficulty: 20, date: 10, endDate: 10, meetTime: 5, meetPoint: 90, mapLink: 500,
  radio: 40, destination: 90, requirement: 90, organiser: 60, details: 1500, kit: 1200, sponsorName: 60, sponsorOffer: 160
};
const TYPES = ["desert", "wadi", "camping", "overland", "social"];
const DATE_RE = /^\d{4}-\d{2}-\d{2}$/;

let schemaReady = false;

export default {
  async fetch(req, env) {
    const url = new URL(req.url);
    const path = url.pathname;
    try {
      if (path.startsWith("/api/")) return await handleApi(req, env, path);
      if (path === "/manifest.webmanifest") return new Response(MANIFEST, { headers: { "content-type": "application/manifest+json", "cache-control": "public, max-age=86400" } });
      const icon = { "/icon-192.png": "i192", "/icon-512.png": "i512", "/apple-touch-icon.png": "i180", "/favicon.ico": "i192", "/og-image.png": "og" }[path];
      if (icon) return new Response(b64(ICONS[icon]), { headers: { "content-type": "image/png", "cache-control": "public, max-age=604800" } });
      if (path === "/" || path === "/index.html" || path === "/board" || path === "/board/") {
        const page = path.startsWith("/board") ? HTML : HOME;
        return new Response(page.replaceAll("__ORIGIN__", url.origin), { headers: { "content-type": "text/html; charset=utf-8", "cache-control": "no-cache", "x-content-type-options": "nosniff", "referrer-policy": "same-origin" } });
      }
      if (path === "/robots.txt") return new Response("User-agent: *\nAllow: /\nDisallow: /board\nDisallow: /api/\n", { headers: { "content-type": "text/plain" } });
      return Response.redirect(url.origin + "/", 302);
    } catch (e) {
      if (e instanceof ApiError) return json({ error: e.code, message: e.message }, e.status);
      console.error(e);
      return json({ error: "server", message: "Something went wrong on our side. Try again in a minute." }, 500);
    }
  }
};

class ApiError extends Error {
  constructor(status, code, message) { super(message); this.status = status; this.code = code; }
}

async function handleApi(req, env, path) {
  if (!env.DB) throw new ApiError(500, "no_database", "The board isn't connected to its database yet.");
  await ensureSchema(env.DB);
  const db = env.DB;
  const organiser = isOrganiser(req, env);

  if (req.method === "GET" && path === "/api/board") {
    const viewer = normalisePhone(req.headers.get("x-phone") || "");
    const ev = await db.prepare("SELECT id, data FROM events WHERE date >= date('now','-180 days') ORDER BY date LIMIT 300").all();
    const events = ev.results.map(r => ({ ...JSON.parse(r.data), id: r.id }));
    const ids = new Set(events.map(e => e.id));
    const su = await db.prepare("SELECT event_id, phone, name, vehicle, people, bringing, note, created_at FROM signups ORDER BY created_at").all();
    const signups = su.results.filter(r => ids.has(r.event_id)).map(r => {
      const s = { eventId: r.event_id, name: r.name, vehicle: r.vehicle || "", people: r.people || 1, bringing: r.bringing || "", note: r.note || "", at: r.created_at, mine: !!viewer && r.phone === viewer };
      if (organiser) s.phone = r.phone;
      return s;
    });
    return json({ events, signups, organiser });
  }

  if (req.method !== "POST") throw new ApiError(405, "method", "Not allowed.");
  const body = await readBody(req);

  switch (path) {
    case "/api/organiser": {
      if (!orgCode(env)) throw new ApiError(500, "no_code", "No organiser code has been set up yet. Add ORGANISER_CODE under Production settings and redeploy.");
      if (!safeEqual(String(body.code || "").trim(), orgCode(env))) throw new ApiError(403, "bad_code", "That code isn't right. Check with Richard.");
      return json({ ok: true });
    }

    case "/api/phone": {
      const phone = normalisePhone(body.phone);
      if (!phone) throw new ApiError(400, "bad_phone", "That doesn't look like a mobile number. Try 050 123 4567 or +971 50 123 4567.");
      return json({ phone });
    }

    case "/api/signup": {
      const eventId = String(body.eventId || "");
      const phone = normalisePhone(body.phone);
      const name = clip(body.name, 60);
      if (!name) throw new ApiError(400, "no_name", "Add your name so people know who's coming.");
      if (!phone) throw new ApiError(400, "bad_phone", "That doesn't look like a mobile number. Try 050 123 4567 or +971 50 123 4567.");
      const row = await db.prepare("SELECT data FROM events WHERE id = ?").bind(eventId).first();
      if (!row) throw new ApiError(404, "no_event", "That event has been removed.");
      const ev = JSON.parse(row.data);
      if ((ev.endDate || ev.date) < todayDubai()) throw new ApiError(400, "past", "That event has already happened.");
      const people = Math.max(1, Math.min(12, parseInt(body.people, 10) || 1));
      const now = new Date().toISOString();
      await db.prepare(
        `INSERT INTO signups (event_id, phone, name, vehicle, people, bringing, note, created_at, updated_at)
         VALUES (?1, ?2, ?3, ?4, ?5, ?6, ?7, ?8, ?8)
         ON CONFLICT(event_id, phone) DO UPDATE SET name = excluded.name, vehicle = excluded.vehicle, people = excluded.people,
           bringing = excluded.bringing, note = excluded.note, updated_at = excluded.updated_at`
      ).bind(eventId, phone, name, clip(body.vehicle, 60), people, clip(body.bringing, 80), clip(body.note, 120), now).run();
      let waitlisted = false;
      const cap = Number(ev.capacity) || 0;
      if (cap) {
        const pos = await db.prepare("SELECT COUNT(*) AS n FROM signups WHERE event_id = ?1 AND created_at <= (SELECT created_at FROM signups WHERE event_id = ?1 AND phone = ?2)").bind(eventId, phone).first();
        waitlisted = pos.n > cap;
      }
      return json({ ok: true, phone, waitlisted });
    }

    case "/api/cancel": {
      const phone = normalisePhone(body.phone);
      if (!phone) throw new ApiError(400, "bad_phone", "We couldn't tell who you are on this phone. Use 'Enter your number' at the bottom of the page.");
      const r = await db.prepare("DELETE FROM signups WHERE event_id = ? AND phone = ?").bind(String(body.eventId || ""), phone).run();
      if (!r.meta.changes) throw new ApiError(404, "not_found", "We couldn't find your sign-up for this event.");
      return json({ ok: true });
    }

    case "/api/events": {
      if (!organiser) throw new ApiError(403, "not_organiser", "Only organisers can post events. Log in with the organiser code first.");
      const data = {};
      for (const [k, max] of Object.entries(EVENT_FIELDS)) data[k] = clip(body[k], max);
      data.capacity = Math.max(0, Math.min(60, parseInt(body.capacity, 10) || 0));
      if (!TYPES.includes(data.type)) data.type = "social";
      if (!data.title) throw new ApiError(400, "no_title", "Give the event a name.");
      if (!DATE_RE.test(data.date)) throw new ApiError(400, "bad_date", "Pick a date.");
      if (data.endDate && (!DATE_RE.test(data.endDate) || data.endDate < data.date)) throw new ApiError(400, "bad_end", "The end date is before the start date.");
      if (data.mapLink && !/^https?:\/\//i.test(data.mapLink)) throw new ApiError(400, "bad_map", "The map link should start with https://");
      const now = new Date().toISOString();
      let id = String(body.id || "");
      if (id) {
        const old = await db.prepare("SELECT data FROM events WHERE id = ?").bind(id).first();
        if (!old) throw new ApiError(404, "no_event", "That event has been removed.");
        const merged = { ...JSON.parse(old.data), ...data, updatedAt: now };
        await db.prepare("UPDATE events SET date = ?, data = ?, updated_at = ? WHERE id = ?").bind(data.date, JSON.stringify(merged), now, id).run();
      } else {
        id = crypto.randomUUID().replace(/-/g, "").slice(0, 12);
        await db.prepare("INSERT INTO events (id, date, data, created_at, updated_at) VALUES (?, ?, ?, ?, ?)").bind(id, data.date, JSON.stringify({ ...data, createdAt: now }), now, now).run();
      }
      return json({ ok: true, id });
    }

    case "/api/events/delete": {
      if (!organiser) throw new ApiError(403, "not_organiser", "Only organisers can delete events.");
      const id = String(body.id || "");
      await db.batch([
        db.prepare("DELETE FROM signups WHERE event_id = ?").bind(id),
        db.prepare("DELETE FROM events WHERE id = ?").bind(id)
      ]);
      return json({ ok: true });
    }
  }
  throw new ApiError(404, "not_found", "Not found.");
}

async function ensureSchema(db) {
  if (schemaReady) return;
  await db.batch([
    db.prepare("CREATE TABLE IF NOT EXISTS events (id TEXT PRIMARY KEY, date TEXT NOT NULL, data TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL)"),
    db.prepare("CREATE TABLE IF NOT EXISTS signups (event_id TEXT NOT NULL, phone TEXT NOT NULL, name TEXT NOT NULL, vehicle TEXT, people INTEGER NOT NULL DEFAULT 1, bringing TEXT, note TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, PRIMARY KEY (event_id, phone))")
  ]);
  schemaReady = true;
}

function isOrganiser(req, env) {
  const code = (req.headers.get("x-organiser-code") || "").trim();
  return !!orgCode(env) && !!code && safeEqual(code, orgCode(env));
}

function orgCode(env) { return String(env.ORGANISER_CODE || "").trim(); }

function safeEqual(a, b) {
  if (a.length !== b.length) return false;
  let d = 0;
  for (let i = 0; i < a.length; i++) d |= a.charCodeAt(i) ^ b.charCodeAt(i);
  return d === 0;
}

// UAE-friendly: 050 123 4567 -> +971501234567; 00xx -> +xx; +xx kept.
function normalisePhone(raw) {
  let p = String(raw || "").trim().replace(/[\s\-().]/g, "");
  if (!p) return "";
  if (p.startsWith("00")) p = "+" + p.slice(2);
  if (/^0\d{8,9}$/.test(p)) p = "+971" + p.slice(1);
  else if (/^5\d{8}$/.test(p)) p = "+971" + p;
  else if (/^971\d{8,9}$/.test(p)) p = "+" + p;
  return /^\+\d{8,15}$/.test(p) ? p : "";
}

function todayDubai() {
  return new Date(Date.now() + 4 * 3600 * 1000).toISOString().slice(0, 10);
}

function clip(v, max) { return String(v ?? "").trim().slice(0, max); }

async function readBody(req) {
  const len = Number(req.headers.get("content-length") || 0);
  if (len > 20000) throw new ApiError(413, "too_big", "That's too much text.");
  try { return await req.json(); } catch { throw new ApiError(400, "bad_json", "Something went wrong sending that. Try again."); }
}

function json(obj, status = 200) {
  return new Response(JSON.stringify(obj), { status, headers: { "content-type": "application/json", "cache-control": "no-store" } });
}

function b64(s) {
  const bin = atob(s);
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  return out;
}
